<div class="quote-items"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px"><h3>Itens e materiais</h3><button type="button" class="btn-aurora btn-outline-aurora btn-sm-aurora" id="add-item"><?=svg_icon('plus',14)?> Adicionar item</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Material do catálogo</th><th>Descrição *</th><th>Qtd.</th><th>Un.</th><th>Custo unitário (R$)</th><th>Subtotal</th><th></th></tr></thead><tbody id="quote-items-body"></tbody></table></div><p class="hint">O valor unitário pode ser ajustado para serviços personalizados. Não há baixa automática de estoque ao orçar.</p></div>
<div class="divider-line"></div><div class="form-grid cols-3"><div class="field"><label>Mão de obra estimada (R$)</label><input class="quote-math" name="labor_cost" type="number" step="0.01" min="0" value="<?=e($edit['labor_cost']??'0')?>" required></div><div class="field"><label>Acréscimo sobre custo (%)</label><input class="quote-math" name="markup_pct" type="number" step="0.01" min="0" max="1000" value="<?=e($edit['markup_pct']??'35')?>" required></div><div class="field"><label>Impostos estimados (%)</label><input class="quote-math" name="tax_pct" type="number" step="0.01" min="0" max="100" value="<?=e($edit['tax_pct']??'0')?>" required></div><div class="field"><label>Desconto (R$)</label><input class="quote-math" name="discount" type="number" step="0.01" min="0" value="<?=e($edit['discount']??'0')?>" required></div><div class="field span-2"><label>Notas para o cliente</label><textarea name="notes"><?=e($edit['notes']??'')?></textarea></div></div>
<div class="items-total"><div><span>Materiais / Serviços</span><strong id="q-materials">R$ 0,00</strong></div><div><span>+ Mão de obra</span><strong id="q-labor">R$ 0,00</strong></div><div><span>Preço com acréscimo</span><strong id="q-sale">R$ 0,00</strong></div><div><span>+ Tributos / − Desconto</span><strong id="q-adjust">R$ 0,00</strong></div><div class="grand"><span>Total estimado</span><strong id="q-total">R$ 0,00</strong></div></div>
<div class="form-footer"><button type="submit" class="btn-aurora"><?=svg_icon('check',16)?> Salvar orçamento</button><a href="<?=e(url('quotes'))?>" class="btn-aurora btn-outline-aurora">Cancelar</a></div></form></div></details><?php endif;?>
<div class="panel"><div class="panel-header"><div><h2>Propostas cadastradas</h2><p>Controle do histórico comercial por cliente</p></div><span class="tag"><?=count($quotes)?> propostas</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Proposta</th><th>Cliente</th><th>Valor</th><th>Validade</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($quotes as $q):?><tr><td><strong><?=e($q['code'])?></strong><small><?=e($q['title'])?></small></td><td><?=e($q['customer_name'])?><small><?=e($q['project_title']??'')?></small></td><td><strong><?=e(money($q['total']))?></strong></td><td><?=e(date_br($q['valid_until']))?></td><td><?=status_badge($q['status'])?></td><td><div class="table-actions"><a href="<?=e(url('quotes.print',['id'=>$q['id']]))?>" target="_blank" rel="noopener" class="btn-aurora btn-outline-aurora btn-sm-aurora">Ver / PDF</a><?php if(allow(['sales'])&&in_array($q['status'],['draft','sent'],true)):?><a href="<?=e(url('quotes',['edit'=>$q['id']]))?>#editor" class="btn-aurora btn-outline-aurora btn-sm-aurora"><?=svg_icon('edit',14)?></a><form method="post" action="<?=e(url('quotes.status'))?>" style="display:flex;gap:5px"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($q['id'])?>"><select name="status" class="inline-select" aria-label="Estado do orçamento"><?php foreach(['draft','sent','approved','rejected'] as $s): if($s==='draft'&&$q['status']==='sent')continue;?><option value="<?=$s?>" <?=$q['status']===$s?'selected':''?>><?=e(label_status($s))?></option><?php endforeach;?></select><button class="btn-aurora btn-sm-aurora">Salvar</button></form><?php endif;?><?php if($q['status']==='approved'&&!$q['work_order_id']&&allow(['sales','production'])):?><form method="post" action="<?=e(url('quotes.order'))?>" data-confirm="Gerar ordem de produção a partir deste orçamento aprovado?"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($q['id'])?>"><button class="btn-aurora btn-sm-aurora">Gerar OP</button></form><?php endif;?><?php if($q['work_order_id']):?><a href="<?=e(url('production',['history'=>$q['work_order_id']]))?>" class="btn-aurora btn-outline-aurora btn-sm-aurora">OP vinculada</a><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$quotes):?><tr><td colspan="6" class="empty">Nenhum orçamento cadastrado.</td></tr><?php endif;?></tbody></table></div></div>
<script>
(function(){
 const materials=<?=json_encode($materials,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?>;
 const prefill=<?=json_encode($editItems,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?>;
 const form=document.getElementById('quote-form');if(!form)return;
 const tbody=document.getElementById('quote-items-body');let idx=0;
 function addRow(item={}){
   const n=idx++,tr=document.createElement('tr');
   const cell=(el)=>{const td=document.createElement('td');td.appendChild(el);tr.appendChild(td);return el;};
   const input=(key,value,type='text')=>{const el=document.createElement('input');el.type=type;el.className='search-input';el.style.minWidth=type==='number'?'82px':'160px';el.name=`items[${n}][${key}]`;el.value=value??'';if(type==='number'){el.min='0';el.step='0.001';}return el;};
   const select=document.createElement('select');select.className='inline-select';select.style.minWidth='175px';select.name=`items[${n}][material_id]`;
   select.add(new Option('Personalizado / Serviço',''));for(const m of materials)select.add(new Option(m.name,m.id));select.value=item.material_id??'';cell(select);
   const desc=input('description',item.description??'');desc.required=true;cell(desc);
   const amount=input('quantity',item.quantity??'1','number');amount.min='0.001';amount.required=true;amount.style.minWidth='70px';cell(amount);
   const unit=input('unit',item.unit??'un');unit.style.width='65px';unit.style.minWidth='65px';unit.maxLength=15;cell(unit);
   const cost=input('unit_cost',item.unit_cost??'0','number');cost.step='0.01';cost.required=true;cell(cost);
   const sum=document.createElement('strong');cell(sum);
   const remove=document.createElement('button');remove.type='button';remove.className='btn-aurora btn-outline-aurora btn-sm-aurora';remove.textContent='×';remove.title='Remover item';cell(remove);
   remove.addEventListener('click',()=>{tr.remove();calculate()});
   select.addEventListener('change',()=>{const m=materials.find(x=>String(x.id)===select.value);if(m){desc.value=m.name;unit.value=m.unit;cost.value=m.cost;}calculate()});
   for(const control of [amount,cost])control.addEventListener('input',calculate);
   tbody.append(tr);
   function calculateRow(){sum.textContent=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(amount.value)||0)*(Number(cost.value)||0));}
   tr.calculateRow=calculateRow;calculate();
 }
 function calculate(){let base=0;for(const tr of tbody.children){const qty=Number(tr.querySelector('[name$="[quantity]"]')?.value)||0;const cost=Number(tr.querySelector('[name$="[unit_cost]"]')?.value)||0;base+=qty*cost;tr.calculateRow?.();}
  const get=k=>Number(form.elements.namedItem(k)?.value)||0,labor=get('labor_cost'),markup=get('markup_pct'),tax=get('tax_pct'),discount=get('discount');
  const round=n=>Math.round((n+Number.EPSILON)*100)/100,sale=round(round(base+labor)*(1+markup/100)),adj=round(sale*tax/100)-discount,total=Math.max(0,round(sale+adj));
  const fmt=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);
  for(const [id,v] of [['q-materials',base],['q-labor',labor],['q-sale',sale],['q-adjust',adj],['q-total',total]])document.getElementById(id).textContent=fmt(v);
 }
 document.getElementById('add-item').addEventListener('click',()=>addRow());
 form.querySelectorAll('.quote-math').forEach(el=>el.addEventListener('input',calculate));
 const client=document.getElementById('quote-customer'),project=document.getElementById('quote-project');
 client.addEventListener('change',()=>{for(const opt of project.options)if(opt.value)opt.hidden=opt.dataset.customer!==client.value;if(project.selectedOptions[0]?.hidden)project.value='';});client.dispatchEvent(new Event('change'));
 for(const i of prefill)addRow(i);if(prefill.length===0)addRow();calculate();
})();
</script>
